/* getrandom(2) example: Obtaining cryptographically secure random data */
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <errno.h>
#include <sys/random.h> // Includes definition of getrandom and flags

#define REQUESTED_BYTES 32

int main() {
    unsigned char random_data[REQUESTED_BYTES];
    ssize_t bytes_read;

    // Request 32 bytes using default urandom source (flags=0),
    // blocking only if the source is uninitialized.
    bytes_read = getrandom(random_data, REQUESTED_BYTES, 0);

    if (bytes_read == -1) {
        perror("getrandom failed");
        return EXIT_FAILURE;
    }

    if (bytes_read < REQUESTED_BYTES) {
        // This case is rare for small reads on an initialized system.
        fprintf(stderr, "Warning: Only %zd bytes were read.\n", bytes_read);
    }

    printf("Successfully read %zd random bytes.\n", bytes_read);
    printf("Hex data: ");
    for (size_t i = 0; i < bytes_read; i++) {
        printf("%02x", random_data[i]);
    }
    printf("\n");

    return EXIT_SUCCESS;
}
